"use client";

import { useParams } from "next/navigation";
import { useState } from "react";
import { adminPost } from "@/services/admin-api";
import { toast } from "@/components/portal";
import { AdminActionDialog, AdminButton, AdminCard, AdminLoad, AdminPage, AdminTable, StateBadge, formatAdminDate, formatAdminMoney, useAdminQuery, useAdminToken } from "@/components/admin-ui";
import { AdminVendorPayout } from "@/components/admin-payout";
import { chargerCapability } from "@/services/charger-specs";

type Vendor={id:string;name:string;type:string;phone:string|null;address:string;lat:number;lng:number;description:string|null;image_url:string|null;operating_hours:string|null;is_active:boolean;verification_status:string;current_stage:string|null;completed_stages:string[];document_references:unknown[];created_at:string;services:{id:string;service_type:string;display_name:string;price_inr:string;capacity:number|null;supported_connectors:string[]|null;max_power_kw:string|number|null;is_active:boolean}[];bookings:number;payouts_enabled:boolean;razorpay_linked_account_id:string|null;commission_rate_bps_override:number|null;kyc_status:string|null;kyc_reference:string|null;kyc_gstin:string|null;kyc_pan_masked:string|null;bank_account_masked:string|null;kyc_verified_at:string|null};
type Page<T>={items:T[];total:number};
type Me={permissions:string[]};
type Finance={gross_revenue:string;completed_refunds:string;platform_fee:string|null;vendor_payout:string|null;payout_status:string;commission_rate_bps:number;routed_inr:string;planned_inr:string;failed_transfers:number;payouts_enabled:boolean};
type Slot={id:string;slot_start_time:string;slot_end_time:string;capacity:number;active_bookings:number;price_inr:string;status:string;service_type:string};
const tabs=["Overview","Bookings","Revenue","Services","Availability","Transactions","Payouts","Documents","Audit History"] as const;
// The revenue tab used to promise "nothing has been transferred" for every vendor. Once routing
// exists that is wrong, so the notice is read from the ledger state the API already computes.
const ROUTING_NOTICE:Record<string,string>={
  calculated_only:"No transfer rows are recorded for this business, so the vendor balance below is a calculation and no money has moved.",
  planned_only:"Transfer instructions are recorded with each captured payment, but no verified provider event has confirmed them yet, so nothing has settled.",
  partially_routed:"Some transfers are confirmed by the provider and others are still planned. The routed and planned figures below come from the payout ledger.",
  routed:"Every ledger row is confirmed by a verified provider event, so the routed figure is money that has actually left the platform.",
};
export default function VendorDetailPage(){
  const {vendorId}=useParams<{vendorId:string}>();const token=useAdminToken();const [tab,setTab]=useState<(typeof tabs)[number]>("Overview");const [action,setAction]=useState("");const [busy,setBusy]=useState(false);
  const vendorQ=useAdminQuery<Vendor>(`/vendors/${vendorId}`,token);const financeQ=useAdminQuery<Finance>(tab==="Revenue"?`/vendors/${vendorId}/financials`:"",token);
  const bookingsQ=useAdminQuery<Page<{booking_id:string;status:string;customer_name:string;service_type:string;slot_start_time:string;amount_inr:string;payment_status:string}>>(tab==="Bookings"?`/bookings?vendor_id=${vendorId}&limit=50`:"",token);
  const slotsQ=useAdminQuery<Slot[]>(tab==="Availability"?`/vendors/${vendorId}/availability`:"",token);
  const txQ=useAdminQuery<Page<{transaction_id:string;booking_id:string;status:string;amount_inr:string;created_at:string}>>(tab==="Transactions"?`/transactions?vendor_id=${vendorId}&limit=50`:"",token);
  const auditQ=useAdminQuery<Page<{action:string;role_name:string;reason:string|null;created_at:string;before_state:unknown;after_state:unknown;request_metadata:unknown}>>(tab==="Audit History"?`/audit-logs?entity_type=vendor&entity_id=${vendorId}&limit=50`:"",token);
  const meQ=useAdminQuery<Me>("/me",token);
  const permissions=meQ.data?.permissions??[];
  const canManageRouting=permissions.includes("payouts:manage");
  const canReviewKyc=permissions.includes("vendor_onboarding:manage");
  const canReadTransfers=permissions.includes("payouts:read")||canManageRouting;
  const canSeePayouts=canReadTransfers||canReviewKyc||canManageRouting;
  const visibleTabs=tabs.filter((name)=>name!=="Payouts"||canSeePayouts);
  async function perform(reason:string){if(!token||!action)return;setBusy(true);try{await adminPost(`/vendors/${vendorId}/action`,token,{action,reason});toast(`Vendor ${action.replaceAll("_"," ")} recorded`);setAction("");vendorQ.reload();}catch(e){toast(e instanceof Error?e.message:"Vendor action failed");}finally{setBusy(false);}}
  const vendor=vendorQ.data;
  return <><AdminPage eyebrow="VENDOR PROFILE" title={vendor?.name??"Vendor detail"} description="Review business profile, operational history, and recorded decisions." action={<div className="admin-actions">{vendor?.verification_status==="approved"?<AdminButton variant="danger" onClick={()=>setAction("suspend")}>Suspend</AdminButton>:vendor?.verification_status==="suspended"?<AdminButton onClick={()=>setAction("reactivate")}>Reactivate</AdminButton>:vendor&&["pending","under_review","changes_requested"].includes(vendor.verification_status)&&<><AdminButton onClick={()=>setAction("approve")}>Approve</AdminButton><AdminButton variant="secondary" onClick={()=>setAction("request_changes")}>Request changes</AdminButton><AdminButton variant="danger" onClick={()=>setAction("reject")}>Reject</AdminButton></>}</div>}/>
    <AdminLoad loading={vendorQ.loading} error={vendorQ.error} data={vendor} retry={vendorQ.reload}>{(v)=><AdminCard><div className="admin-vendor-hero"><div><h2>{v.name}</h2><p>{v.type} · {v.address}</p><div className="admin-actions"><StateBadge value={v.verification_status}/><StateBadge value={v.is_active?"active":"inactive"}/></div></div><div className="admin-vendor-coords">{v.lat.toFixed(5)}, {v.lng.toFixed(5)}<small>Stored business location</small></div></div>
      <nav className="admin-tabs" aria-label="Vendor detail tabs">{visibleTabs.map((name)=><button key={name} className={tab===name?"selected":""} onClick={()=>setTab(name)}>{name}</button>)}</nav>
      {tab==="Overview"&&<div className="admin-stack">{v.image_url&&<img className="admin-vendor-photo" src={v.image_url} alt={`${v.name} business`} loading="lazy"/>}<div className="admin-detail-grid">{[["Vendor ID",v.id],["Vendor type",v.type],["Phone",v.phone??"Not provided"],["Address",v.address],["Operating hours",v.operating_hours??"Not provided"],["Created",formatAdminDate(v.created_at,true)],["Verification stage",v.current_stage??"application"],["Bookings",String(v.bookings)]].map(([label,value])=><div className="admin-detail-item" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div><div className="admin-callout">Description · {v.description??"No business description recorded."}</div></div>}
      {tab==="Bookings"&&<AdminLoad loading={bookingsQ.loading} error={bookingsQ.error} data={bookingsQ.data} retry={bookingsQ.reload} empty={Boolean(bookingsQ.data&&!bookingsQ.data.items.length)} emptyTitle="No vendor bookings">{(d)=><AdminTable headers={["Booking","Customer","Service","Slot","Amount","Payment","Status"]}>{d.items.map((r)=><tr key={r.booking_id}><td>{r.booking_id.slice(0,12)}…</td><td>{r.customer_name}</td><td>{r.service_type.replaceAll("_"," ")}</td><td>{formatAdminDate(r.slot_start_time,true)}</td><td>{formatAdminMoney(r.amount_inr)}</td><td><StateBadge value={r.payment_status}/></td><td><StateBadge value={r.status}/></td></tr>)}</AdminTable>}</AdminLoad>}
      {tab==="Revenue"&&<AdminLoad loading={financeQ.loading} error={financeQ.error} data={financeQ.data} retry={financeQ.reload}>{(d)=><><div className="admin-note" style={{marginBottom:12}}>A {d.commission_rate_bps/100}% calculation policy applies to new verified charging payments; completed refunds reduce the estimate. Older verified payments were grandfathered at 0%. {ROUTING_NOTICE[d.payout_status]??"Settlement state is not recognised, so check the payout ledger before acting."}</div><div className="admin-detail-grid">{[["Gross captured",formatAdminMoney(d.gross_revenue)],["Completed refunds",formatAdminMoney(d.completed_refunds)],["Calculated commission",formatAdminMoney(d.platform_fee)],["Estimated vendor balance · unpaid",formatAdminMoney(d.vendor_payout)],["Settlement state",d.payout_status],["Routed by the provider",formatAdminMoney(d.routed_inr)],["Planned · not confirmed",formatAdminMoney(d.planned_inr)],["Failed transfers",String(d.failed_transfers)],["Routing switch",d.payouts_enabled?"Enabled for this business":"Disabled for this business"]].map(([label,value])=><div className="admin-detail-item" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div></>}</AdminLoad>}
      {tab==="Services"&&<AdminTable headers={["Service","Type","Charger capability","Capacity","Price","State"]}>{v.services.map((s)=>{const specs=chargerCapability(s);return <tr key={s.id}><td className="primary-cell">{s.display_name}</td><td>{s.service_type.replaceAll("_"," ")}</td><td>{specs?<strong>{specs.summary}</strong>:"—"}{specs?.incomplete&&<small style={{display:"block"}}>Route search skips this service</small>}</td><td>{s.capacity??"—"}</td><td>{formatAdminMoney(s.price_inr)}</td><td><StateBadge value={s.is_active?"active":"paused"}/></td></tr>;})}</AdminTable>}
      {tab==="Availability"&&<AdminLoad loading={slotsQ.loading} error={slotsQ.error} data={slotsQ.data} retry={slotsQ.reload} empty={Boolean(slotsQ.data&&!slotsQ.data.length)} emptyTitle="No availability slots">{(items)=><AdminTable headers={["Slot","Service","Capacity","Active bookings","Price","Status"]}>{items.map((s)=><tr key={s.id}><td>{formatAdminDate(s.slot_start_time,true)} – {formatAdminDate(s.slot_end_time,true)}</td><td>{s.service_type.replaceAll("_"," ")}</td><td>{s.capacity}</td><td>{s.active_bookings}</td><td>{formatAdminMoney(s.price_inr)}</td><td><StateBadge value={s.status}/></td></tr>)}</AdminTable>}</AdminLoad>}
      {tab==="Transactions"&&<AdminLoad loading={txQ.loading} error={txQ.error} data={txQ.data} retry={txQ.reload} empty={Boolean(txQ.data&&!txQ.data.items.length)} emptyTitle="No transactions">{(d)=><AdminTable headers={["Transaction","Booking","Amount","Status","Created"]}>{d.items.map((r)=><tr key={r.transaction_id}><td>{r.transaction_id.slice(0,12)}…</td><td>{r.booking_id.slice(0,12)}…</td><td>{formatAdminMoney(r.amount_inr)}</td><td><StateBadge value={r.status}/></td><td>{formatAdminDate(r.created_at,true)}</td></tr>)}</AdminTable>}</AdminLoad>}
      {tab==="Payouts"&&<AdminVendorPayout vendorId={vendorId} vendor={v} canManageRouting={canManageRouting} canReviewKyc={canReviewKyc} canReadTransfers={canReadTransfers} onChanged={()=>{vendorQ.reload();financeQ.reload();}}/>}
      {tab==="Documents"&&<><div className="admin-detail-grid">{v.completed_stages.map((stage)=><div className="admin-detail-item" key={stage}><small>Completed stage</small><strong>{stage.replaceAll("_"," ")}</strong></div>)}</div><div className="admin-callout" style={{marginTop:12}}>Document references only. VoltStop never stores uploaded documents or full banking credentials; the Payouts tab keeps the masked PAN and account reference that routing decisions need.</div>{!!v.document_references.length&&<pre className="admin-json">{JSON.stringify(v.document_references,null,2)}</pre>}</>}
      {tab==="Audit History"&&<AdminLoad loading={auditQ.loading} error={auditQ.error} data={auditQ.data} retry={auditQ.reload} empty={Boolean(auditQ.data&&!auditQ.data.items.length)} emptyTitle="No vendor audit actions">{(d)=><AdminTable headers={["Action","Role","Reason","Timestamp","Change"]}>{d.items.map((r,i)=><tr key={`${r.action}-${i}`}><td className="primary-cell">{r.action}</td><td>{r.role_name}</td><td>{r.reason??"—"}</td><td>{formatAdminDate(r.created_at,true)}</td><td><details><summary>Inspect</summary><pre className="admin-json">{JSON.stringify({before:r.before_state,after:r.after_state,request:r.request_metadata},null,2)}</pre></details></td></tr>)}</AdminTable>}</AdminLoad>}
    </AdminCard>}</AdminLoad>{action&&vendor&&<AdminActionDialog title={`${action.replaceAll("_"," ")} · ${vendor.name}`} description={`Confirm the ${action.replaceAll("_"," ")} vendor action.`} impact="This changes vendor access to driver discovery and creates an immutable audit record." confirmLabel={action.replaceAll("_"," ")} busy={busy} onClose={()=>setAction("")} onConfirm={perform}/>}</>;
}
